    /**
     * The diagnostic of this rule at [location], the path of the element it concerns.
     */
    fun diagnostic(location: String): ProducerDiagnostic = ProducerDiagnostic(
        code = code,
        reason = reason,
        location = location,
        severity = severity,
    )

    companion object {

        /**
         * The rule [code] names, or `null` when it names none.
         */
        fun fromCode(code: String): ExchangeGraphRule? = entries.firstOrNull { it.code == code }
    }
}
